import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.BZzouRtU.js";const k=JSON.parse('{"title":"UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr","description":"","frontmatter":{"title":"UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr","study":{"source":"C++ Wiki","status":"published","summary":"UObjectのGCと、UPROPERTY・TObjectPtr・TWeakObjectPtrなどの参照が寿命にどう関係するかを調べる。","section":"reference","format":"article","domain":"game"}},"headers":[],"relativePath":"game/unreal/gc-and-object-pointers.md","filePath":"game/unreal/gc-and-object-pointers.md"}'),r={name:"game/unreal/gc-and-object-pointers.md"};function n(l,t,o,d,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="ueのガベージコレクションと-uproperty・tobjectptr・tweakobjectptr" tabindex="-1">UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr <a class="header-anchor" href="#ueのガベージコレクションと-uproperty・tobjectptr・tweakobjectptr" aria-label="Permalink to &quot;UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>UEはUObjectだけを対象とするマーク&amp;スイープGCを備えています。UEでは<a href="/study/runtime/memory/gc-and-csharp-comparison.html">RAIIとGCの両方</a>を使います。UObjectの寿命を考えるときは、GCがそのポインタを参照として追跡できるかを確認します。</p><h2 id="仕組み-概要" tabindex="-1">仕組み(概要) <a class="header-anchor" href="#仕組み-概要" aria-label="Permalink to &quot;仕組み(概要)&quot;">​</a></h2><ul><li>ルートから、GCへ登録された強参照を辿り、到達できないUObjectを回収します。UObjectのメンバーでは<code>UPROPERTY</code>で宣言した<code>TObjectPtr</code>が基本です</li><li>.NETのGCは管理対象の参照をスタック・レジスタなどから追跡しますが、UEでは通常のC++生ポインタをローカル変数へ入れただけでGCのルートになるわけではありません。ただし、GCに参照を伝える方法は<code>UPROPERTY</code>以外にもあります</li></ul><p>非UObjectの所有者からは<code>FGCObject::AddReferencedObjects</code>で列挙したり、<code>TStrongObjectPtr</code>で保持したりできます。UObject系の<code>AddReferencedObjects</code>による参照列挙もあります。<code>AddToRoot</code>でルートへ追加する場合は、不要になった時点の<code>RemoveFromRoot</code>と対にします。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/unreal-object-handling-in-unreal-engine" target="_blank" rel="noreferrer">UEのオブジェクト管理</a> · <a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/object-pointers-in-unreal-engine" target="_blank" rel="noreferrer">オブジェクトポインタとTStrongObjectPtr</a></p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UCLASS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ATurret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AActor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    GENERATED_BODY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    UPROPERTY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        // GCに「この参照を辿って」と教える</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TObjectPtr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AEnemy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Target;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // → 到達可能なTurretから辿れる強参照</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       //   ただしActorの明示的なDestroyは防がない</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AEnemy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RawTarget;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 // UPROPERTYなし: GCから不可視!</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       // GCはこの参照を辿らず、回収後も値を自動更新しない</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       // (Actorはレベルからの参照やDestroyの規則も持つ)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>GCへ別途登録していない生ポインタを長期保存すると、その参照は対象を延命せず、回収後も自動的に無効化されません。保存する参照の登録方法と、対象の破棄時の扱いを決めます。</p><h2 id="ポインタ型の使い分け-ue5" tabindex="-1">ポインタ型の使い分け(UE5) <a class="header-anchor" href="#ポインタ型の使い分け-ue5" aria-label="Permalink to &quot;ポインタ型の使い分け(UE5)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>型</th><th>意味</th><th>対応する標準C++の概念</th></tr></thead><tbody><tr><td><code>UPROPERTY() TObjectPtr&lt;T&gt;</code></td><td>所有的・強参照(延命する)。UE5でのメンバ宣言の標準形</td><td>shared_ptr的(ただし台帳方式)</td></tr><tr><td><code>TStrongObjectPtr&lt;T&gt;</code></td><td>UPROPERTYを使えない所有者などからGCへ伝える強参照。スコープ終了・Resetで保持を解除する</td><td>スコープで管理する保持ハンドル</td></tr><tr><td><code>TWeakObjectPtr&lt;T&gt;</code></td><td>弱参照(延命しない+<strong>生死を問える</strong> <code>IsValid()</code>)</td><td><a href="/study/languages/cpp/smart-pointers.html">weak_ptr</a></td></tr><tr><td><code>TSoftObjectPtr&lt;T&gt;</code></td><td>アセットへの<strong>パス参照</strong>(ロードを強制しない)</td><td><a href="/study/design/patterns/proxy.html">Proxy</a>(遅延ロード)</td></tr><tr><td>生ポインタ <code>T*</code></td><td>関数引数・ローカルなど<strong>一時的な借用のみ</strong></td><td>非所有生ポインタ(<a href="/study/runtime/memory/ownership-and-borrowing.html">借用</a>)</td></tr></tbody></table><ul><li>使い分けの原則は<a href="/study/runtime/memory/ownership-and-borrowing.html">所有権と借用</a>と同型: <strong>メンバとして保存するならGCに見える形(TObjectPtr+UPROPERTY)か弱参照(TWeakObjectPtr)</strong>、関数スコープの借用は生ポインタで可</li><li>「相手(敵・アイテム)が先に消えるかもしれない参照」は <code>TWeakObjectPtr</code>+IsValid()——<a href="/study/runtime/memory/exercises.html">ロックオンカメラ問題</a>のUE公式解</li></ul><h2 id="actorの破棄はgcだけではない" tabindex="-1">Actorの破棄はGCだけではない <a class="header-anchor" href="#actorの破棄はgcだけではない" aria-label="Permalink to &quot;Actorの破棄はGCだけではない&quot;">​</a></h2><p><code>DestroyActor()</code> は「ゲーム的な破棄」(レベルから除去・マーク)で、メモリ回収は後のGCが行う2段階です。<strong>破棄済みだが未回収</strong>の期間があるため、生存確認は <code>IsValid(actor)</code>(nullチェックでは不十分——UnityのDestroyと<code>== null</code>のカスタム比較に似た構図)。</p><h2 id="標準c-ではどう書くか-なぜueはgcか" tabindex="-1">標準C++ではどう書くか / なぜUEはGCか <a class="header-anchor" href="#標準c-ではどう書くか-なぜueはgcか" aria-label="Permalink to &quot;標準C++ではどう書くか / なぜUEはGCか&quot;">​</a></h2><p>標準C++なら<a href="/study/runtime/memory/ownership-and-borrowing.html">所有の木+unique_ptr+ハンドル</a>で設計します。UEがUObjectにGCを選んだ理由:</p><ol><li>レベル・Actor・コンポーネント・アセット・Blueprintが<strong>相互参照する巨大グラフ</strong>であり、所有の木を全プロジェクトに強制するのは非現実的</li><li><strong>Blueprint(非プログラマ)が参照を作る</strong>——所有権設計を要求できない</li><li>エディタでのオブジェクト差し替え・ホットリロードに、到達可能性ベースの回収が都合よい</li></ol><p>一方、<strong>非UObject</strong>(FVector、TArrayの中身、自作の純C++クラス)は完全に標準C++の世界(RAII・値セマンティクス)。<strong>UEプログラマは2つのメモリモデルを常に区別して書いている</strong>のが実態です。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「C#と同じで参照してれば生きてる」— UEのGCへ伝わる強参照が必要です。UPROPERTYのメンバー以外にも登録手段はありますが、通常のローカル生ポインタだけでは保持になりません。また、強参照はActorの明示的なDestroyを防ぐものではありません</li><li>「Destroyしたらnullになる」— Unityの<code>==null</code>偽装に慣れていると、UEの「IsValidで確認」を忘れる。生ポインタは<strong>何も起きない</strong>(dangling)</li><li>UObjectに<code>std::shared_ptr</code>を使う——<strong>禁止</strong>(2つの管理系が衝突)。UObjectはUE式、非UObjectは標準式、と世界を分ける</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>UEのGCへ伝えていない生ポインタを保存すると何が起きますか。UPROPERTY以外の参照登録手段を二つ挙げてください。</li><li>TObjectPtr / TWeakObjectPtr / TSoftObjectPtr / 生ポインタの使い分けは?</li><li>UObjectと非UObjectでメモリ管理の流儀がどう分かれますか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>「ロックオンカメラ(ターゲットの敵が消えるかもしれない)」を、(a) 標準C++(<a href="/study/runtime/memory/exercises.html">メモリ管理の演習</a>を参照)、(b) UE(TWeakObjectPtr+IsValid)の両方の骨格で書き、同じ問題への2つの解法として対比してください。</p><hr><p>関連項目：<a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponent</a> | <a href="/study/game/unreal/">この分野の学習ガイド</a> | <a href="/study/game/unreal/reflection-and-uht.html">リフレクションとUHT</a></p>`,25)])])}const g=e(r,[["render",n]]);export{k as __pageData,g as default};
